import{_ as o,o as c,c as s,a2 as a}from"./chunks/framework.CqGPl1zp.js";const d="/newx-doc/assets/%E5%B7%A5%E4%BD%9C%E5%8F%B0.B_dM9wtA.png",i="/newx-doc/assets/%E8%B4%A2%E5%8A%A1%E9%A6%96%E9%A1%B5.DdKV5dux.png",t="/newx-doc/assets/%E5%BD%95%E5%87%AD%E8%AF%81.oTAZfPYl.png",_=JSON.parse('{"title":"移动端 FMS","description":"","frontmatter":{},"headers":[],"relativePath":"fms/mobile.md","filePath":"fms/mobile.md","lastUpdated":null}'),r={name:"fms/mobile.md"};function p(l,e,n,m,u,f){return c(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="移动端-fms" tabindex="-1">移动端 FMS <a class="header-anchor" href="#移动端-fms" aria-label="Permalink to &quot;移动端 FMS&quot;">​</a></h1><p>友情提示</p><p>本文讲解 yudao 移动端（uni-app 版）的 FMS 系统，重点说清楚两件事：FMS 已经提供手机端、当前支持的主要功能。</p><ul><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-uniapp" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-uniapp</a>，基于 <code>uni-app</code> + <code>Vue3</code> + <code>wot-ui</code> 实现，支持 H5、微信小程序等多端。</li><li>后端：复用 PC 端同一套 <code>yudao-module-fms</code> 模块与 <code>/fms/**</code> 接口，移动端只是换了一层 UI。</li></ul><h2 id="_1-移动端功能" tabindex="-1">1. 移动端功能 <a class="header-anchor" href="#_1-移动端功能" aria-label="Permalink to &quot;1. 移动端功能&quot;">​</a></h2><ul><li>工作台：FMS 财务首页、账套切换和常用功能入口。</li><li>凭证管理：录凭证、查凭证、凭证详情、凭证汇总表，支持移动凭证和整理凭证。</li><li>账簿管理：明细账、总账、科目余额表、多栏账、核算项目账、数量金额账。</li><li>报表管理：资产负债表、利润表、现金流量表。</li><li>结账管理：结账概况、结账方案、结账模板和期间结账。</li><li>设置管理：账套管理、财务参数、财务指标、币别、科目设置、辅助核算、财务初始余额、凭证字、常用摘要、凭证模板。</li></ul><p><img src="'+d+'" alt="FMS 移动端工作台"></p><p>进入工作台后，点击「FMS 财务管理」即可看到移动端 FMS 的功能分组；页面路由为 <code>/pages/index/index</code>，FMS 菜单由 <code>src/pages/index/menu.json</code> 配置。</p><p><img src="'+i+'" alt="FMS 移动端财务首页"></p><p>财务首页位于 <code>src/pages-statistics/fms/home/index.vue</code>，由 <code>home-shortcuts.vue</code>、<code>metric-cards.vue</code> 和 <code>metric-charts.vue</code> 组成，调用 <code>src/api/fms/home/index.ts</code> 获取当前账套指标、快捷入口和趋势数据。</p><p><img src="'+t+'" alt="FMS 移动端录凭证"></p><p>录凭证页面位于 <code>src/pages-fms/voucher/create/index.vue</code>，分录使用 <code>voucher-entry-form.vue</code>，摘要库和科目选择分别调用 <code>src/api/fms/config/digest</code>、<code>src/api/fms/config/subject</code>，保存时调用 <code>src/api/fms/voucher</code>。</p><p>移动端页面统一使用 <code>src/pages-fms</code> 下的页面组件，并通过 <code>src/api/fms</code> 调用后端接口；账套切换由 <code>src/pages-fms/store/fms.ts</code> 维护，未选择账套时由 <code>components/account-set/guide.vue</code> 引导进入账套管理。</p><h2 id="_2-启动与发布" tabindex="-1">2. 启动与发布 <a class="header-anchor" href="#_2-启动与发布" aria-label="Permalink to &quot;2. 启动与发布&quot;">​</a></h2><ul><li>启动：参考 <a href="./../quick-start-front">《快速启动【前端】》</a> 文档的「1.4 Vue3 + uni-app 版本」小节，在 <code>yudao-ui-admin-uniapp-next-v4</code> 仓库执行 <code>pnpm dev:h5</code>，即可启动 H5 调试页面。</li><li>发布：参考 <a href="./../admin-uniapp/deploy">《运行发布》</a> 文档；根据 uni-app 的目标平台执行 H5、微信小程序或 App 构建。</li></ul><p>启动完成后，在工作台选择「FMS 财务管理」即可进入移动端 FMS；页面路由使用 <code>/pages-fms/**</code>，例如结账页为 <code>/pages-fms/closing/index</code>，录凭证页为 <code>/pages-fms/voucher/create/index</code>。</p><h2 id="_3-代码位置" tabindex="-1">3. 代码位置 <a class="header-anchor" href="#_3-代码位置" aria-label="Permalink to &quot;3. 代码位置&quot;">​</a></h2><ul><li>页面：<code>src/pages-statistics/fms/</code>（财务首页）、<code>src/pages-fms/</code>（凭证、账簿、报表、结账和设置）</li><li>接口：<code>src/api/fms/</code></li><li>状态：<code>src/pages-fms/store/fms.ts</code></li><li>公共组件：<code>src/pages-fms/components/</code>、<code>src/pages-fms/utils/</code></li></ul>',18)])])}const g=o(r,[["render",p]]);export{_ as __pageData,g as default};
